import{_ as o,c as a,a0 as t,o as n}from"./chunks/framework.CWWCFBQd.js";const u=JSON.parse('{"title":"Troubleshooting FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faqs/faqs-of-troubleshooting.md","filePath":"guide/faqs/faqs-of-troubleshooting.md"}'),i={name:"guide/faqs/faqs-of-troubleshooting.md"};function r(s,e,d,l,h,c){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="troubleshooting-faqs" tabindex="-1">Troubleshooting FAQs <a class="header-anchor" href="#troubleshooting-faqs" aria-label="Permalink to &quot;Troubleshooting FAQs&quot;">​</a></h1><h2 id="node-site" tabindex="-1">Node Site: <a class="header-anchor" href="#node-site" aria-label="Permalink to &quot;Node Site:&quot;">​</a></h2><h3 id="what-is-the-minimum-configuration-in-my-values-yaml-for-a-node-deployment" tabindex="-1">What is the minimum configuration in my <code>values.yaml</code> for a Node deployment? <a class="header-anchor" href="#what-is-the-minimum-configuration-in-my-values-yaml-for-a-node-deployment" aria-label="Permalink to &quot;What is the minimum configuration in my `values.yaml` for a Node deployment?&quot;">​</a></h3><p>Add the node’s hostname, Hub client ID and secret, and crypto private key. Also set <code>expose.type</code> to <code>ingress</code> or <code>gateway</code>. For details and an example, see <a href="/guide/deployment/node-installation.html#preparation">Node Installation: preparation</a>.</p><h3 id="how-do-i-access-to-my-node-without-a-domain-name" tabindex="-1">How do I access to my Node without a domain name? <a class="header-anchor" href="#how-do-i-access-to-my-node-without-a-domain-name" aria-label="Permalink to &quot;How do I access to my Node without a domain name?&quot;">​</a></h3><p>Set <code>expose.type</code> to <code>none</code> and leave the hostname blank. Then port-forward the Node UI, Hub Adapter, and Keycloak services. The Node UI will be available at <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>. For further information, visit <a href="/guide/deployment/node-installation.html#deploying-without-a-domain-name">Node Installation: deploying without a Domain Name</a>.</p><h3 id="how-do-i-expose-my-node-behind-a-tls-configuration-or-a-reverse-proxy" tabindex="-1">How do I expose my Node behind a TLS configuration or a reverse proxy? <a class="header-anchor" href="#how-do-i-expose-my-node-behind-a-tls-configuration-or-a-reverse-proxy" aria-label="Permalink to &quot;How do I expose my Node behind a TLS configuration or a reverse proxy?&quot;">​</a></h3><p>For a TLS config, create a Kubernetes TLS secret with <code>kubectl create secret tls tls-secret --key my-flame-node.key --cert my-flame-node.crt</code>, then set <code>tlsSecretName: tls-secret</code> in the ingress settings. Check more in <a href="/guide/deployment/node-troubleshooting.html#setting-up-tls-connection">Node Troubleshooting:TLS setup</a>.</p><p>The reverse-proxy instructions in the troubleshooting page are considered for Airflow; for the FLAME Node’s proxy assumptions, visit <a href="/guide/deployment/node-installation.html">Node Installation</a>.</p>',9)])])}const p=o(i,[["render",r]]);export{u as __pageData,p as default};
